<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/shared/cost-workbook-history.php';
$dsn=getenv('CW_TEST_DSN');if(!$dsn){fwrite(STDERR,"CW_TEST_DSN missing\n");exit(2);} $pdo=new PDO($dsn,(string)getenv('CW_TEST_DB_USER'),(string)getenv('CW_TEST_DB_PASSWORD'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
