foreach($sets as $t=>$c){$id=$c['order'];$search=$c['search'][0];$pdo->exec("CREATE TABLE `$t` (`$id` INT PRIMARY KEY, `$search` VARCHAR(190), amount DECIMAL(12,2), pdf_path VARCHAR(255))");for($i=1;$i<=($t==='supplier_invoices'?55:2);$i++){$st=$pdo->prepare("INSERT INTO `$t` VALUES(?,?,?,?)");$st->execute([$i,$i===1?'Synthetic <script>alert(&quot;x&quot;)</script>':"Synthetic $t $i",$i.'.25','private/test.pdf']);}}
