$hash=static function()use($pdo,$sets):string{$all=[];foreach(array_merge(array_keys($sets),['cw_history_guard']) as$t)$all[$t]=$pdo->query("SELECT * FROM `$t` ORDER BY 1")->fetchAll(PDO::FETCH_ASSOC);return hash('sha256',serialize($all));};$before=$hash();$assertions=0;$ok=static function(bool$v,string$m)use(&$assertions):void{$assertions++;if(!$v)throw new RuntimeException($m);};
