$escaped=htmlspecialchars('Synthetic <script>alert(&quot;x&quot;)</script>',ENT_QUOTES,'UTF-8');$ok(str_contains($escaped,'&lt;script&gt;'),'escaping');$ok($before===$hash(),'all fixture hashes unchanged');
